// A Func is a function value, along with any variables it captures. See
// [Value.Func].
//
// It may be a named function, a function literal, or a method value.
type Func struct{}

// DeclaredFunc returns the function as it's declared in the program: the named
// function, the function literal, or for a method value, the method.
//
// ok is false if f is a method value of an interface method, and the
// receiver's dynamic type isn't known, or differs between timelines.
//
// It never returns a wrapper function generated by the ssa package.
func (f Func) DeclaredFunc() (_ *ssa.Function, ok bool) {
	panic("not implemented")
}

// Receiver returns the receiver bound into a method value.
//
// ok is false if the function isn't a method value.
func (f Func) Receiver() (_ Value, ok bool) {
	panic("not implemented")
}

// Captures returns the values of the variables that the function captures, in
// the order of [ssa.Function.FreeVars].
func (f Func) Captures() []Value {
	panic("not implemented")
}

// Predict predicts a call to f, made at the point where f was predicted.
//
// args is the set of arguments to pass to the function call. For a method
// value, it doesn't include the receiver, which is already bound.
//
// To construct an argument, use [Known], [KnownAs], [Sentinel] or [Unknown].
// Missing arguments, or the zero [Value], are treated as unknown.
//
// The result's [Prediction.Parent] is the prediction that f came from, so it
// shares that prediction's variables.
//
// For a method value, the prediction is of the wrapper function that the ssa
// package generates for it, which calls the declared method.
func (f Func) Predict(ctx context.Context, args ...Value) (*Prediction, error) {
	_ = ctx
	_ = args

	panic("not implemented")
}
